// Merges what the agent just learned with the lead saved earlier in this chat, then scores it.
const incoming = $('When Executed by Another Workflow').first().json;
const existing = $input.first().json || {};

const clean = (v) => (v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim());
const pick = (field) => clean(incoming[field]) ?? clean(existing[field]);

function normalizePhone(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/\D/g, '');
  if (digits.startsWith('63')) digits = digits.slice(2);
  else if (digits.startsWith('0')) digits = digits.slice(1);
  return /^9\d{9}$/.test(digits) ? '+63' + digits : null;
}
function normalizeEmail(raw) {
  if (!raw) return null;
  const email = String(raw).trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
}

const lead = {
  session_id: incoming.session_id,
  name: pick('name'),
  phone: normalizePhone(pick('phone')),
  email: normalizeEmail(pick('email')),
  service: pick('service'),
  urgency: ['emergency', 'pain', 'routine'].includes(pick('urgency')?.toLowerCase()) ? pick('urgency').toLowerCase() : null,
  is_new_patient: /^(yes|true)$/i.test(incoming.is_new_patient ?? '') ? true
    : /^(no|false)$/i.test(incoming.is_new_patient ?? '') ? false : (existing.is_new_patient ?? null),
  payment: pick('payment'),
  preferred_time: pick('preferred_time'),
  notes: pick('notes'),
};

// Score 0-100: urgency, value of the service, how reachable they are, how soon they want to come in.
const HIGH_VALUE = /implant|braces|orthodont|aligner|invisalign|veneer|crown|root canal|whitening/i;
const SOON = /\b(asap|today|tonight|tomorrow|this week|right now|ngayon|bukas|karon|ugma)\b/i;
let score = { emergency: 35, pain: 25, routine: 5 }[lead.urgency] ?? 0;
if (lead.service) score += HIGH_VALUE.test(lead.service) ? 25 : 10;
if (lead.phone) score += 10;
if (lead.email) score += 10;
if (lead.name) score += 5;
if (lead.preferred_time) {
  const when = Date.parse(lead.preferred_time);
  const days = Number.isNaN(when) ? null : (when - Date.now()) / 86400000;
  if (SOON.test(lead.preferred_time) || (days !== null && days <= 7)) score += 15;
}
if (lead.is_new_patient) score += 5;
score = Math.min(score, 100);

const tier = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
const tags = [tier];
if (lead.urgency === 'emergency') tags.push('emergency');
if (lead.is_new_patient) tags.push('new-patient');
if (/hmo|maxicare|intellicare|medicard|philcare/i.test(lead.payment ?? '')) tags.push('hmo');

const missing = [];
if (!lead.name) missing.push('name');
if (!lead.phone && !lead.email) missing.push('phone or email');
if (!lead.service) missing.push('service');
if (!lead.preferred_time) missing.push('preferred_time');

const LOCKED = ['booked', 'handoff', 'no_show', 'completed', 'lost'];
const status = LOCKED.includes(existing.status) ? existing.status
  : lead.name && (lead.phone || lead.email) && lead.service ? 'qualified' : 'new';

// Alert staff once, the first time a lead turns hot or reports an emergency.
const wasFlagged = existing.tier === 'hot' || (existing.tags ?? []).includes('emergency');
const alert_staff = !wasFlagged && (tier === 'hot' || lead.urgency === 'emergency');

return [{ json: { ...lead, score, tier, status, tags, missing, alert_staff } }];

const lead = $('Normalize and Score').first().json;
return [{ json: {
  saved: true,
  lead_id: $('Upsert Lead').first().json.id,
  score: lead.score,
  tier: lead.tier,
  status: lead.status,
  still_missing: lead.missing,
} }];
